class Solution {
public:
    int minFlips(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        int row_flips = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n / 2; ++c) {
                if (grid[r][c] != grid[r][n - 1 - c]) {
                    row_flips++;
                }
            }
        }
        int col_flips = 0;
        for (int c = 0; c < n; ++c) {
            for (int r = 0; r < m / 2; ++r) {
                if (grid[r][c] != grid[m - 1 - r][c]) {
                    col_flips++;
                }
            }
        }
        return min(row_flips, col_flips);
    }
};

class Solution {
    public int minFlips(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int rowFlips = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n / 2; ++c) {
                if (grid[r][c] != grid[r][n - 1 - c]) {
                    rowFlips++;
                }
            }
        }
        int colFlips = 0;
        for (int c = 0; c < n; ++c) {
            for (int r = 0; r < m / 2; ++r) {
                if (grid[r][c] != grid[m - 1 - r][c]) {
                    colFlips++;
                }
            }
        }
        return Math.min(rowFlips, colFlips);
    }
}

var minFlips = function(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let rowFlips = 0;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < Math.floor(n / 2); c++) {
            if (grid[r][c] !== grid[r][n - 1 - c]) {
                rowFlips++;
            }
        }
    }
    let colFlips = 0;
    for (let c = 0; c < n; c++) {
        for (let r = 0; r < Math.floor(m / 2); r++) {
            if (grid[r][c] !== grid[m - 1 - r][c]) {
                colFlips++;
            }
        }
    }
    return Math.min(rowFlips, colFlips);
};
